<script setup>
import {actions,labels,stages,isActive} from '../lib/rules';defineProps({orders:Array,user:Object,busy:Boolean});defineEmits(['action','detail','chat']);
</script>
<template><section><h1>我的订单</h1><p class="muted">交付登记不等于成交，必须由买方本人确认收到。</p><article v-for="o in orders" :key="o.id" class="card"><div class="row"><span class="tag">{{o.stage}}{{o.disputed?' · 争议处理中':''}}</span><small>{{o.id}}</small></div><h2>{{o.title}}</h2><p class="description">{{o.description}}</p><div class="row"><strong class="price">¥ {{Number(o.price).toFixed(2)}}</strong><span>买方 {{o.buyer_name}} / 卖方 {{o.seller_name}}</span></div><div class="steps"><span v-for="stage in [...stages,'已完成']" :key="stage" :class="{current:stage===o.stage}">{{stage}}</span></div><p v-if="o.reason">原因：{{o.reason}}</p><div class="actions"><button v-for="act in actions(o,user)" :key="act" :disabled="busy" @click="$emit('action',o,act)">{{labels[act]}}</button><button @click="$emit('detail',o)">快照与交付详情</button><button @click="$emit('chat',o)">{{isActive(o)?'订单沟通':'查看历史沟通'}}</button></div><p v-if="o.disputed" class="muted">暂停接单、拒单、登记与普通取消；已登记时买方仍可确认。</p><p v-if="o.stage==='待买方确认'" class="muted">未回应不自动完成或取消；完整争议申请入口按V2交付。</p></article><div v-if="!orders.length" class="empty">暂无订单，去发现物品逛逛吧。</div></section></template>
